  var privileged=compare("/api/community/fixed/posts/102",bob,List.of(admin,alice,mod),"GET /api/community/fixed/posts/102 ALLOW DENY DENY","$.OWNER_ID");String note=privileged.packets[0].note;check("matrix precedence repaired",note.contains("기대 ALLOW")&&!note.contains("타인 객체 접근 의심")&&note.contains("설정 충돌"),note);
